-- Migration 113: Adicionar 461 novas referências normativas e modelos de exigências NORMAM-202 a partir de MODELODEEXIGENCIAS.docx
ALTER TABLE analise_planos_referencias_normam MODIFY COLUMN item_norma VARCHAR(255) NULL;
